// =====================================================================
// PROCESADOR SIMPLIFICADO PARA EL DEMO HTML
// Toma el mensaje enviado por el prospecto y los datos del lead
// y genera la respuesta personalizada con IA + Calendly.
// =====================================================================
const body = $input.first().json.body || $input.first().json;
const content = (body.content || body.texto || '').toString().trim();
const lead = body.lead || {};

const nombre = lead.primerNombre || lead.contacto || 'hola';
const empresa = lead.empresa || 'tu empresa';
const sistema = lead.sistema || 'tu sistema ERP';
const facturas = lead.facturas || '500';
const motivo = lead.motivo || 'cambio de sistema';

const lower = content.toLowerCase();
let respuesta = '';
let esInteresado = true;

if (lower.includes('no gracias') || lower.includes('no estamos interesados') || lower.includes('ya no trabajo')) {
  respuesta = `Muchas gracias por responder, ${nombre}. Dejamos asentado en el sistema para no enviarte más mensajes. ¡Que tengas un excelente día!`;
  esInteresado = false;
} else if (lower.includes('caro') || lower.includes('precio') || lower.includes('cuánto sale') || lower.includes('plan')) {
  respuesta = `Te entiendo perfectamente, ${nombre}. Recientemente sacamos esquemas de planes mucho más flexibles que se adaptan al volumen real de facturación de ${empresa} (~${facturas} facturas/mes). ¿Te sirve que lo revisemos 10 minutos en una llamada rápida sin compromiso?`;
} else if (lower.includes('tango') || lower.includes('softland') || lower.includes('sistema') || lower.includes('cambio')) {
  respuesta = `Justamente por eso te escribía, ${nombre}. Mejoramos la integración nativa con ${sistema} para que la contabilización de facturas sea 100% automática sin alterar su configuración actual. ¿Tiene sentido que lo miremos 10 min en una llamada corta esta semana?`;
} else {
  respuesta = `Hola ${nombre}! En Xtract automatizamos la lectura y carga contable de facturas directo a ${sistema}. Lanzamos varias actualizaciones este mes que ahorran más del 70% del tiempo operativo. ¿Te sirve que te lo muestre brevemente en una llamada de 10 min?`;
}

return {
  json: {
    response: respuesta,
    interesado: esInteresado,
    lead_procesado: empresa,
    sistema_erp: sistema
  }
};
